UPDATE mock_exam SET status = #{status}, reviewed_by = #{reviewedBy}, reviewed_at = #{reviewedAt},
    review_note = #{reviewNote}, published_at = #{publishedAt}
WHERE exam_id = #{examId} AND status = 'SUBMITTED'

mapper.select:
SELECT  FROM mock_exam
submitted_by = #{submittedBy}AND status = #{status}
ORDER BY exam_id DESC LIMIT #{offset}, #{size}

mapper.update:
UPDATE question_bank SET category = #{category}, stem = #{stem}, option_a = #{optionA}, option_b = #{optionB},
    option_c = #{optionC}, option_d = #{optionD}, correct_option = #{correctOption},
    explanation = #{explanation}, enabled = #{enabled}
WHERE question_id = #{questionId} AND exam_id = #{examId}

UPDATE exam_answer ea JOIN question_bank q ON q.question_id = ea.question_id
SET ea.score_awarded = CASE WHEN ea.selected_option = q.correct_option THEN 5 ELSE 0 END
WHERE ea.attempt_id = #{attemptId}
